findDuplicateGroups(): Array<MemoryDuplicateGroup & { entries: MemoryEntry[] }> {
  const byBucket = new Map<string, MemoryEntry[]>();
  for (const e of this.entries.values()) {
    const k = `${e.scope}|${e.projectId ?? ""}|${e.sessionId ?? ""}`;
    byBucket.set(k, [...(byBucket.get(k) ?? []), e]);
  }
  return [...byBucket.values()].flatMap((g) => clusterDuplicateMemories(g));
}
